// Real-Chromium video-thumbnail-picker evidence (5.20.0): boots the harness
// server (the REAL PostComposer + the REAL in-browser frame capture at
// ?screen=composer — no login, no backend), attaches a real decodable H.264
// fixture (generated by ffmpeg at run time — a time-varying test pattern, so
// the candidate frames are visibly distinct), and drives the picker end to
// end: the tray's "Thumbnail" chip → the sheet's captured candidates → a pick
// → the tray's <video poster> (what you see is what ships).
//
// The receipt (video-thumbnail-receipt.json, written even on failure) records
// the fixture's probed duration/dims, the sheet's candidate times (the real
// thumbnailCandidateTimes math on the real duration), the applied poster, and
// page errors per viewport.
//
// Run from marketing/web10-social:
//   SCREENSHOT_OUTPUT_DIR="$PWD/../../.context/video-thumbnail" node screenshots/video-thumbnail.mjs
import { chromium } from 'playwright';
import { spawn, execFileSync } from 'node:child_process';
import { fileURLToPath } from 'node:url';
import path from 'node:path';
import fs from 'node:fs';

const __dirname = path.dirname(fileURLToPath(import.meta.url));
const root = path.resolve(__dirname, '..');
const PORT = Number(process.env.SCREENSHOT_PORT || 4507);
const BASE_URL = `http://localhost:${PORT}/screenshots/harness/index.html`;

const VIEWPORTS = {
  desktop: { width: 1440, height: 900 },
  '375': { width: 375, height: 812 },
};

const OUTPUT_DIR = process.env.SCREENSHOT_OUTPUT_DIR || path.join(root, '..', '..', '.context', 'video-thumbnail');
const FIXTURE_DIR = path.join(__dirname, 'harness', 'fixtures');
const FIXTURE = path.join(FIXTURE_DIR, 'video-thumbnail-sample.mp4');

async function waitForServer(url, timeoutMs = 30000) {
  const start = Date.now();
  while (Date.now() - start < timeoutMs) {
    try {
      const res = await fetch(url);
      if (res.ok) return;
    } catch { /* not up yet */ }
    await new Promise((r) => setTimeout(r, 300));
  }
  throw new Error(`Harness server did not come up at ${url}`);
}

const runner = process.env.VITE_RUNNER || 'bunx';
const server = spawn(runner, ['vite', '--config', 'screenshots/vite.config.ts'], {
  cwd: root,
  stdio: 'inherit',
  env: { ...process.env, SCREENSHOT_PORT: String(PORT) },
});

// A 12s, 480x270, time-varying test pattern (testsrc2 moves its clock +
// patterns every second) so the three candidate frames are visibly distinct.
// H.264/yuv420p — the exact codec class the composer accepts.
function ensureFixture() {
  fs.mkdirSync(FIXTURE_DIR, { recursive: true });
  if (fs.existsSync(FIXTURE)) return;
  execFileSync('ffmpeg', [
    '-hide_banner', '-loglevel', 'error', '-y',
    '-f', 'lavfi', '-i', 'testsrc2=s=480x270:r=30',
    '-t', '12',
    '-c:v', 'libx264', '-pix_fmt', 'yuv420p', '-preset', 'veryfast',
    '-movflags', '+faststart',
    FIXTURE,
  ]);
}
ensureFixture();

// Fetch the fixture as a File inside the page (the real attach pipeline —
// validateMedia + getVideoInfo — decodes it for real).
async function attachFixture(page) {
  const buffer = await page.evaluate(async () => {
    const res = await fetch('/screenshots/harness/fixtures/video-thumbnail-sample.mp4');
    if (!res.ok) throw new Error(`fixture fetch failed: ${res.status}`);
    const bytes = new Uint8Array(await res.arrayBuffer());
    return Array.from(bytes);
  });
  const file = {
    name: 'thumbnail-sample.mp4',
    type: 'video/mp4',
    buffer: Buffer.from(buffer),
  };
  const input = page.locator('input[type="file"]').first();
  await input.setInputFiles(file);
}

const receipt = {
  started: new Date().toISOString(),
  app: 'web10-social (harness, real PostComposer + real in-browser frame capture at ?screen=composer)',
  claim:
    'The creator picks the video thumbnail at upload time: the tray\'s "Thumbnail" chip opens the picker, three frames are captured in-browser (real decode), and the pick becomes the tray item\'s <video poster> (5.20.0).',
  fixture: { url: '/screenshots/harness/fixtures/video-thumbnail-sample.mp4', duration_target_s: 12, resolution: '480x270', codec: 'h264/yuv420p (regenerated at run time when absent)' },
  viewports: {},
};

let browser;
try {
  fs.mkdirSync(OUTPUT_DIR, { recursive: true });
  await waitForServer(BASE_URL);
  browser = await chromium.launch();

  for (const [label, viewport] of Object.entries(VIEWPORTS)) {
    const context = await browser.newContext({ viewport, deviceScaleFactor: 2 });
    const page = await context.newPage();
    const pageLog = [];
    page.on('pageerror', (err) => {
      const line = `[pageerror] ${err.message}`;
      pageLog.push(line);
      console.error(line);
    });
    page.on('console', (msg) => {
      if (msg.type() === 'error') {
        const line = `[page:console] ${msg.text()}`;
        pageLog.push(line);
        console.error(line);
      }
    });

    const entry = { pages: [] };
    receipt.viewports[label] = entry;

    await page.goto(`${BASE_URL}?screen=composer`, { waitUntil: 'networkidle' });
    await page.waitForSelector('[data-testid="post-composer"] >> visible=true', { timeout: 15000 });
    await attachFixture(page);

    // The real attach pipeline: the tray settles once getVideoInfo decodes
    // the fixture (duration/dims are the browser's real read).
    await page.waitForSelector('[data-testid="media-tray"] >> visible=true', { timeout: 20000 });
    await page.waitForFunction(
      () => {
        const tray = document.querySelector('[data-testid="media-tray"]');
        return !!tray && !tray.querySelector('.animate-spin');
      },
      null,
      { timeout: 30000 },
    );
    const badge = await page.$eval('[data-testid="media-tray"] .font-mono', (el) => el.textContent).catch(() => null);
    entry.trayDims = badge;
    entry.chip = await page.locator('[data-testid="media-thumbnail-button"]').textContent();

    // 1) The tray with the video + the "Thumbnail" chip.
    await page.screenshot({ path: path.join(OUTPUT_DIR, `video-thumbnail-tray-${label}.png`) });
    entry.pages.push(`video-thumbnail-tray-${label}.png`);

    // 2) Open the picker — the REAL in-browser capture runs (sequential
    //    seeks on one <video>, canvas frames, webp encode).
    await page.click('[data-testid="media-thumbnail-button"]');
    await page.waitForSelector('[data-testid="video-thumbnail-sheet"] >> visible=true', { timeout: 15000 });
    await page.waitForSelector('[data-testid="video-thumbnail-frame-0"] >> visible=true', { timeout: 30000 });
    entry.candidateLabels = await page.$$eval(
      '[data-testid^="video-thumbnail-frame-"]',
      (tiles) => tiles.map((t) => t.textContent?.trim() ?? ''),
    );
    entry.previewShown = await page.locator('[data-testid="video-thumbnail-preview"] img').count() > 0;

    // 3) The sheet with the real candidates (default = candidate 0).
    await page.screenshot({ path: path.join(OUTPUT_DIR, `video-thumbnail-sheet-${label}.png`) });
    entry.pages.push(`video-thumbnail-sheet-${label}.png`);

    // 4) Pick the last frame → the preview + selection follow the pick.
    const lastTile = page.locator('[data-testid^="video-thumbnail-frame-"]').last();
    await lastTile.click();
    await page.waitForTimeout(300); // preview settle
    await page.screenshot({ path: path.join(OUTPUT_DIR, `video-thumbnail-picked-${label}.png`) });
    entry.pages.push(`video-thumbnail-picked-${label}.png`);

    // 5) Apply → the sheet closes and the tray's <video> carries the pick as
    //    its poster (the object URL the composer minted).
    await page.click('[data-testid="video-thumbnail-apply"]');
    await page.waitForSelector('[data-testid="video-thumbnail-sheet"]', { state: 'detached', timeout: 15000 });
    const poster = await page.$eval(
      '[data-testid="media-tray"] video',
      (el) => el.getAttribute('poster') ?? null,
    );
    entry.posterApplied = !!poster && poster.startsWith('blob:');
    entry.posterPreview = await page.evaluate((url) => {
      if (!url) return null;
      return new Promise((resolve) => {
        const img = new Image();
        img.onload = () => resolve({ complete: true, naturalWidth: img.naturalWidth, naturalHeight: img.naturalHeight });
        img.onerror = () => resolve({ complete: false });
        img.src = url;
      });
    }, poster);
    entry.chipAfter = await page.locator('[data-testid="media-thumbnail-button"]').textContent();

    // 6) The tray with the chosen poster.
    await page.waitForTimeout(400);
    await page.screenshot({ path: path.join(OUTPUT_DIR, `video-thumbnail-poster-${label}.png`) });
    entry.pages.push(`video-thumbnail-poster-${label}.png`);

    if (!entry.posterApplied || !entry.posterPreview?.complete || entry.candidateLabels.length < 2) {
      entry.pageErrors = pageLog.length ? pageLog : 'none';
      fs.writeFileSync(path.join(OUTPUT_DIR, 'video-thumbnail-receipt.json'), JSON.stringify(receipt, null, 2));
      throw new Error(`thumbnail pick did not ship on ${label}: ${JSON.stringify({ poster: entry.posterApplied, preview: entry.posterPreview, labels: entry.candidateLabels })}`);
    }
    entry.pageErrors = pageLog.length ? pageLog : 'none';
    await context.close();
  }

  receipt.finished = new Date().toISOString();
  const receiptOut = path.join(OUTPUT_DIR, 'video-thumbnail-receipt.json');
  fs.writeFileSync(receiptOut, JSON.stringify(receipt, null, 2));
  console.log('wrote', receiptOut);
  console.log(JSON.stringify(receipt, null, 2));
} catch (err) {
  console.error(err.message);
  fs.writeFileSync(path.join(OUTPUT_DIR, 'video-thumbnail-receipt.json'), JSON.stringify(receipt, null, 2));
  process.exitCode = 1;
} finally {
  if (browser) await browser.close();
  server.kill('SIGTERM');
}
